/* @lc app=leetcode id=3139 lang=kotlin */ class Solution { fun minCostToEqualizeArray(nums: IntArray, cost1: Int, cost2: Int): Int = nums.max().let { mx -> nums.min().let { mn -> nums.sumOf { it.toLong() }.let { sm -> ((if (cost1 * 2L <= cost2) cost1.toLong() * (nums.size.toLong() * mx - sm) else (mx..2 * mx).minOf { t -> (nums.size.toLong() * t - sm).let { tot -> (t - mn).toLong().let { d -> minOf(tot / 2, tot - d).let { p -> p * cost2 + (tot - 2 * p) * cost1 } } } }) % 1_000_000_007).toInt() } } } }